window.docContents[68].resolve({"/LindenstraussPolynomials/Theorems/#LindenstraussPolynomials___polynomial_lindenstrauss_vector":{"contents":"Theorem thm:vector (polynomial Lindenstrauss theorem, vector-valued).\nFor every continuous n-homogeneous polynomial P : X → Y (n ≥ 1, Y complete) and\nevery ε > 0 there are a continuous n-homogeneous polynomial Q with ‖Q - P‖ < ε and\na point z of the closed unit ball of X** with ‖Q̃(z)‖ = ‖Q̃‖ = ‖Q‖. \n\n","context":"","header":"LindenstraussPolynomials.polynomial_lindenstrauss_vector","id":"/LindenstraussPolynomials/Theorems/#LindenstraussPolynomials___polynomial_lindenstrauss_vector"}});